%[text] 本图讲：细胞复用
%[text] 迁移阶段活跃的细胞，扣除从学会阶段活跃的部分，恰好等于Naive活跃的细胞占比
outDirUNC = "\\Data-Server-2\个人数据\张天夫\202601";
try
	if ~isfolder(outDirUNC)
		mkdir(outDirUNC);
	end
catch
end
MB=TransferLearning.MOpBaseline; %[output:425e9d55] %[output:39cba025] %[output:875eb4ab] %[output:40bb9dab] %[output:9b99ca65] %[output:877e6ff4] %[output:70f8aa68] %[output:68ef196e] %[output:9b62276b] %[output:37955c19] %[output:40bd7b6e] %[output:4708418c] %[output:90ff37c7] %[output:3910d0bb] %[output:102d7ad4] %[output:1b29e880] %[output:449e3cd8] %[output:5d1c1ebc] %[output:69dd25c5] %[output:1185ad6b] %[output:3ed02f12] %[output:4002fd1a] %[output:378daf7b] %[output:950ad531] %[output:53003023] %[output:0dee5800] %[output:74352dd3] %[output:64442ffe] %[output:54035623] %[output:1483d3ea] %[output:6a0f0770] %[output:22703207] %[output:6af1d0f9] %[output:83293bc8] %[output:23d0aa32] %[output:6917dc08] %[output:80a72512] %[output:72a25178] %[output:42e17b50] %[output:99a23394] %[output:344a13e5] %[output:4bcbebce] %[output:5cba3d10] %[output:73baeda4] %[output:8147cc39] %[output:545a6082] %[output:8bd7b044] %[output:37921405] %[output:56542b8b] %[output:50a1556a] %[output:208e80a4] %[output:32495820] %[output:68514d6e] %[output:48b91aa6] %[output:8d56bd2c] %[output:22704927] %[output:9be5ff03] %[output:1e054867] %[output:09195403] %[output:43f3064a] %[output:3fcea25d] %[output:89dfdac9] %[output:8235e4fa] %[output:1e5fe8a2] %[output:6812d804] %[output:19d00022] %[output:6a2d2edb] %[output:6f71000c] %[output:0207f4b1] %[output:4f8ea012] %[output:06ac7256] %[output:2a2a9bad] %[output:39ac06e3] %[output:9d6484b7] %[output:9ebc725e] %[output:95a42a1f] %[output:7968c642] %[output:267d1161] %[output:00e22828] %[output:1072f2e9] %[output:72cfd5ac] %[output:8d6fd9f1] %[output:1a6de2ca] %[output:695935ae] %[output:2e04a09f] %[output:3a0c14a0] %[output:9c45fdcf] %[output:5c2683c4] %[output:8792626e] %[output:08d4418b] %[output:55d3a6f9] %[output:40885167] %[output:72b7138c] %[output:878e5254] %[output:514710a7] %[output:1089ac34] %[output:882cd9b0] %[output:24c601db] %[output:4e0d70b6] %[output:1bc74b4e] %[output:93fd056f] %[output:3a9e7c6a] %[output:38016bf6] %[output:32193032] %[output:01dfd1de] %[output:6e791c3c] %[output:9c66054b] %[output:1bb570aa] %[output:7234fe86] %[output:7de45df9]
%%
GroupNtats=MB.QueryNTATS(UniExp.ReadQueryTable(TransferLearning.ProjectPath('尝试查询表.xlsx'),"CellReuse"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
for P=["Naive","Learned","Transfer"]
	Table=GroupNtats.(P);
	Table.Active=max(Table.NTATS(:,25:32),[],2)>std(Table.NTATS(:,1:24),[],2)*3;
	Table.Phase(:)=P;
	GroupNtats.(P)=Table;
end
NLT=[GroupNtats.Naive;GroupNtats.Learned;GroupNtats.Transfer];
[~,Index]=ismember(NLT.CellUID,MB.Cells.CellUID);
NLT.ZLayer=MB.Cells.ZLayer(Index);
TransferActive=NLT.CellUID(NLT.Active&NLT.Phase=="Transfer"&NLT.ZLayer=="MOp5");
LearnedActive=NLT.CellUID(NLT.Active&NLT.Phase=="Learned"&NLT.ZLayer=="MOp5");
TransferProportion=nnz(NLT.Active&NLT.Phase=="Transfer"&NLT.ZLayer=="MOp5")./nnz(NLT.Phase=="Transfer"&NLT.ZLayer=="MOp5");
TransferLearnedProportion=mean(ismember(TransferActive,LearnedActive));
NaiveProportion=nnz(NLT.Active&NLT.Phase=="Naive"&NLT.ZLayer=="MOp5")./nnz(NLT.Phase=="Naive"&NLT.ZLayer=="MOp5");
NaiveProportion/TransferProportion+TransferLearnedProportion-1 %[output:943625fb]
%%
TransferActiveCells=NLT.CellUID(NLT.Active&NLT.Phase=="Transfer");
%%
TransferActiveNLT=NLT(ismember(NLT.CellUID,TransferActiveCells),:);
%%
LTActiveCells=TransferActiveNLT.CellUID(TransferActiveNLT.Active&TransferActiveNLT.Phase=="Learned");
%%
TActiveCells=TransferActiveNLT.CellUID(~TransferActiveNLT.Active&TransferActiveNLT.Phase=="Learned");
%%
LTActiveTransfer=NLT(ismember(NLT.CellUID,LTActiveCells)&NLT.Phase=="Transfer",:);
%%
TActiveTransfer=NLT(ismember(NLT.CellUID,TActiveCells)&NLT.Phase=="Transfer",:);
%%
LTActiveTransfer25Lines=groupsummary(LTActiveTransfer,"ZLayer",'mean','NTATS');
%%
TActiveTransfer25Lines=groupsummary(TActiveTransfer,"ZLayer",'mean','NTATS');
%%
LTActiveTransfer25Lines.LearnedActive(:)=true;
TActiveTransfer25Lines.LearnedActive(:)=false;
Transfer25Lines=[LTActiveTransfer25Lines;TActiveTransfer25Lines];
%%
Fig=figure; %[output:258abdea]
Lines=plot(Transfer25Lines.mean_NTATS.'); %[output:258abdea]
legend(Lines,string(Transfer25Lines.ZLayer)+string(Transfer25Lines.LearnedActive),Location=MATLAB.Graphics.OptimizedLegendLocation(Lines)); %[output:258abdea]
print(Fig, fullfile(outDirUNC, '迁移活跃细胞按是否从学会阶段活跃继承划分.svg'), '-dsvg'); %[output:258abdea]
%%
%[text] 结论：迁移前20回合活跃的5层细胞，占比恰好等于，Naive前20回合活跃的5层细胞占比，与从学会阶段继承而来的5层细胞占比之和。活跃判据：1s内响应超过基线3倍标准差
%%
Fig=figure; %[output:0fc6e3a4]
Bars=bar(["Transfer 💡💧";"Naive 💡💧"],[TransferProportion*[(1-TransferLearnedProportion),TransferLearnedProportion];NaiveProportion,0],'stacked',FaceColor='flat'); %[output:0fc6e3a4]
Bars(1).CData=[1,0,1;0,1,0]; %[output:0fc6e3a4]
Bars(2).CData=[0,0,0]; %[output:0fc6e3a4]
legend(Bars,["Learned-inactive","Learned-active"]); %[output:0fc6e3a4]
ylabel('Active cells proportion'); %[output:0fc6e3a4]
title('Active L5 cells'); %[output:0fc6e3a4]
print(Fig, fullfile(outDirUNC, '比例相加.svg'), '-dsvg'); %[output:0fc6e3a4]
%[text] 迁移阶段L5共有6%活跃细胞，其中1.5%是从学会阶段继承，剩余4.5%恰等于Naive活跃细胞占比。
%%
V7=TransferLearning.Vacation7;
%%
V7GroupNtats=V7.QueryNTATS(UniExp.ReadQueryTable(TransferLearning.ProjectPath('尝试查询表.xlsx'),"CellReuse.V7"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
V7GroupNtats.Active=max(V7GroupNtats.NTATS(:,25:32,:),[],2)>std(V7GroupNtats.NTATS(:,1:24,:),[],2).*3;
[~,Index]=ismember(V7GroupNtats.CellUID,V7.Cells.CellUID);
V7GroupNtats.ZLayer=V7.Cells.ZLayer(Index);
%%
V7LearnedCells=V7GroupNtats.CellUID(V7GroupNtats.Active.Learned&V7GroupNtats.ZLayer=="MOp2/3");
V7TransferCells=V7GroupNtats.CellUID(V7GroupNtats.Active.Transfer&V7GroupNtats.ZLayer=="MOp2/3");
V7TransferLearnedProportion=mean(ismember(V7TransferCells,V7LearnedCells));
V7TransferProportion=numel(V7TransferCells)./nnz(V7GroupNtats.ZLayer=="MOp2/3");
V7TransferProportion*V7TransferLearnedProportion %[output:4e9cccdb]
%%
%[text] 初始活跃的光水细胞，是仅仅对光响应的吗？
GroupNtatsWithCue=MB.QueryNTATS(UniExp.ReadQueryTable(TransferLearning.ProjectPath('尝试查询表.xlsx'),"CellReuse.Cue"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:3fdd7146]
%%
Naive=struct;
Naive.Naive=GroupNtatsWithCue.Naive;
Naive.Cue=GroupNtatsWithCue.NaiveCue;
Naive=UniExp.NtatsCellStrip(Naive);
%%
Naive.Active=max(Naive.NTATS(:,25:32,:),[],2)>std(Naive.NTATS(:,1:24,:),[],2).*3;
[~,Index]=ismember(Naive.CellUID,MB.Cells.CellUID);
Naive.ZLayer=MB.Cells.ZLayer(Index);
NaiveCueProportion=mean(Naive.Active.Cue&Naive.ZLayer=="MOp2/3") %[output:6e19f728]
NaiveAssProportion=mean(Naive.Active.Naive&Naive.ZLayer=="MOp2/3") %[output:9df0d619]
NaiveCAProportion=mean(Naive.Active.Cue&Naive.Active.Naive&Naive.ZLayer=="MOp2/3") %[output:09719dfa]
%%
%[text] RSP活跃细胞占比？
RSPd=TransferLearning.RSPd; %[output:9bc2e599] %[output:101f43f2] %[output:72330cab]
%%
RSPdGroupNtats=RSPd.QueryNTATS(UniExp.ReadQueryTable(TransferLearning.ProjectPath('尝试查询表.xlsx'),"CellReuse.RSPd"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
RSPdGroupNtats.Active=max(RSPdGroupNtats.NTATS(:,25:32,:),[],2)>std(RSPdGroupNtats.NTATS(:,1:24,:),[],2).*3;
[~,Index]=ismember(RSPdGroupNtats.CellUID,RSPd.Cells.CellUID);
RSPdGroupNtats.ZLayer=RSPd.Cells.ZLayer(Index);
%%
RSPdLearnedCells=RSPdGroupNtats.CellUID(RSPdGroupNtats.Active.Learned&RSPdGroupNtats.ZLayer=="RSPd2/3");
RSPdTransferCells=RSPdGroupNtats.CellUID(RSPdGroupNtats.Active.Transfer&RSPdGroupNtats.ZLayer=="RSPd2/3");
RSPdTransferLearnedProportion=mean(ismember(RSPdTransferCells,RSPdLearnedCells));
RSPdTransferProportion=numel(RSPdTransferCells)./nnz(RSPdGroupNtats.ZLayer=="RSPd2/3");
%%


